"""Separately cached DADA2/phylogeny stages; classification remains a DB-bound node."""
def integer(default,minimum=0,maximum=1000):return {'type':'integer','default':default,'minimum':minimum,'maximum':maximum}
P={'threads':integer(2,1,16),'seed':integer(42,0,2147483647)}
CONTRACTS={}
def add(name,inputs,outputs,params=None,tools=None):CONTRACTS[name]={'inputs':inputs,'outputs':outputs+['stage-methods.json'],'parameters':{**P,**(params or {})},'tools':['analysis_python',*(['Rscript'] if tools is None else tools)],'worker_python':'analysis_python','analysis':True}
add('amplicon_primers',['manifest'],['manifest.csv','region-check.json'],{'primers_removed':{'type':'boolean','required':True},'primer_forward':{'type':'string','default':''},'primer_reverse':{'type':'string','default':''},'region':{'type':'string','required':True,'enum':['V4','V3-V4','V1-V2','other']},'min_retained_fraction':{'type':'number','default':.5,'minimum':0,'maximum':1}},tools=['cutadapt'])
add('amplicon_filter',['manifest'],['manifest.csv','read_tracking.csv','R-session.txt'],{'primers_removed':{'type':'boolean','required':True},'trunc_len_forward':integer(240,1),'trunc_len_reverse':integer(160,1),'expected_amplicon_max_length':{'type':'integer','required':True,'minimum':1,'maximum':5000},'min_overlap':integer(12,4,200),'max_ee':{'type':'number','default':2,'minimum':.1,'maximum':10}})
add('amplicon_errors',['manifest'],['forward_error.rds','reverse_error.rds','R-session.txt'])
add('amplicon_denoise',['manifest','forward_error','reverse_error'],['denoised.rds','read_tracking.csv','R-session.txt'])
add('amplicon_merge',['denoised'],['sequence_table.rds','read_tracking.csv','region-lengths.csv','R-session.txt'],{'min_overlap':integer(12,4,200),'min_amplicon_length':{'type':'integer','required':True,'minimum':1,'maximum':5000},'max_amplicon_length':{'type':'integer','required':True,'minimum':1,'maximum':5000}})
add('amplicon_chimera',['sequence_table'],['asv_table.csv','asv_sequences.fasta','read_tracking.csv','R-session.txt'])
add('amplicon_alignment',['sequences'],['aligned.fasta'],tools=['mafft'])
add('amplicon_tree',['alignment'],['rooted.nwk','unrooted.nwk'],tools=['FastTree'])
add('amplicon_unifrac',['table','tree'],['distances.csv'],{'unit':{'type':'string','required':True,'enum':['counts']},'weighted':{'type':'boolean','default':True}},tools=[])
add('amplicon_silva',['asv_sequences'],['asv_taxonomy.csv','dada2-session.txt'],{'min_boot':integer(80,1,100)})
CONTRACTS['amplicon_silva']['databases']=['16s.silva']
for name,contract in CONTRACTS.items():
    contract.update(node_id=name,method_version='0.3.0',entrypoint='scripts/amplicon_stages.R via bioflow_ml.amplicon_nodes.execute' if name in ['amplicon_filter','amplicon_errors','amplicon_denoise','amplicon_merge','amplicon_chimera'] else 'bioflow_ml.amplicon_nodes.execute',version_binding='immutable containing Skill revision plus library-file-hashes.json',input_format='manifest CSV sample_id/read1/read2 and gzipped paired FASTQ; stage RDS, FASTA, Newick or count CSV as declared',output_format='stage-specific files listed in outputs; ASV table is unrarefied integer counts',unit_contract='reads or integer ASV counts; UniFrac output is a distance matrix, taxonomy output is categorical',resource_requirements={'threads_parameter_max':16,'runtime_seconds':3600,'memory':'not OS-enforced; small-data validation only; register scheduler resources before large cohorts'},applicability='Demultiplexed paired reads; explicit primer/region assumptions, length/overlap checks; taxonomy requires a verified SILVA resource; UniFrac requires a matching rooted branch-length tree',log_contract='central task log, stage-methods.json, per-stage read tracking and R-session.txt where applicable',cache_invalidation=['source hashes','input content hashes','parameters and seed','tool/environment registration','database version and checksums'])
